        javascript() {
            return function() {
                if(!this.$el) return;
                const $el = this.$el, isLive = this.isLive;
                const requiredCheckBoxList = $el.querySelectorAll('.ecom-required--checkbox'),
                    forms = document.querySelectorAll('.ecom-product-form--single');
                let files = $el.querySelectorAll('.ecom-product-single__property-file');
                function handlerRequiredCheckbox() {
                    if(requiredCheckBoxList.length > 0) {
                        requiredCheckBoxList.forEach(function(checkboxGroup) {
                            let checkbox_items = checkboxGroup.querySelectorAll('input[type=checkbox]');
                            if(checkbox_items.length == 0) return;
                            let isChecked = false;

                            checkbox_items.forEach(function(checkbox) {
                                if(checkbox.checked) {
                                    isChecked = true;
                                }
                            })

                            if(isChecked) {
                                checkbox_items.forEach(function(checkbox) {
                                    checkbox.required = false;
                                })
                            } else {
                                checkbox_items.forEach(function(checkbox) {
                                    checkbox.required = true;
                                })
                            }
                        })
                    }
                }
                if(forms.length) {
                    forms.forEach(function(form) {
                        form.addEventListener('submit', handlerRequiredCheckbox);
                    });
                }
                function handleChooseDate() {
                    const elDate = $el.querySelector('.ecom-product-single__property-datetime-local');
                    if(!elDate) return;
                    elDate.addEventListener('change', function() {
                        const data = elDate.dataset.excludeDay ?? '';
                        const error = elDate.dataset.errorText ?? "I'm sorry, we are closed on this day.";
                        if(data === '') return;
                        const selectedDate = new Date(elDate.value);
                        const selectedDay = selectedDate.toLocaleDateString('en-US', { weekday: 'short' }).toLowerCase(); // Get day of week (ex: "mon")
                        if(data.includes(',')) {
                            let datas = data.split(',');

                            if (datas.includes(selectedDay)) {
                                alert(error);
                                elDate.value = "";
                            }
                        }
                        else {
                           if(data === selectedDay) {
                                alert(error);
                                elDate.value = "";
                           }
                        }
                    })
                }
                handleChooseDate();
                if (files.length > 0 && isLive) {
                    files.forEach(function(file, index) {
                        let label = file.nextElementSibling,
                            labelVal = label.querySelector('.ecom-product-single-form-input--file-text').innerHTML;
                        if(/iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream) {
                            label.addEventListener('click', function() {
                                file.click();
                            });
                        }

                        file.addEventListener('change', function(e) {
                            var sizeErrorEl = this.dataset.sizeErrorId ? document.getElementById(this.dataset.sizeErrorId) : null;
                            var maxSize = parseFloat(this.dataset.maxSize || '0');
                            if (maxSize > 0 && this.files && this.files.length > 0) {
                                var totalSize = 0;
                                for (var i = 0; i < this.files.length; i++) { totalSize += this.files[i].size; }
                                if (totalSize > maxSize * 1024 * 1024) {
                                    this.value = '';
                                    label.querySelector('.ecom-product-single-form-input--file-text').innerHTML = labelVal;
                                    if (sizeErrorEl) {
                                        sizeErrorEl.innerHTML = this.dataset.sizeError || '';
                                        sizeErrorEl.style.display = 'block';
                                    }
                                    return;
                                }
                            }
                            if (sizeErrorEl) sizeErrorEl.style.display = 'none';
                            let fileName = '';
                            if (this.files && this.files.length > 1) {
                                fileName = this.dataset.multipleCaption || '';
                                fileName = fileName.replace('{count}', this.files.length);
                            } else {
                                fileName = e.target.value.split('\\').pop();
                            }

                            if (fileName) {
                                label.querySelector('.ecom-product-single-form-input--file-text').innerHTML = fileName;
                            } else {
                                label.querySelector('.ecom-product-single-form-input--file-text').innerHTML = labelVal;
                            }
                        });
                    });
                }

            }
        }
    },
    methods: {
        formWidth(field) {
            return {
                width: field.settings?.width
                    ? `calc(${
                          field.settings.width !== '100%'
                              ? field.settings.width
                              : field.settings.width +
                                ` + ${
                                    this.data.settings.column_gap
                                        ? this.data.settings.column_gap / 2 + 'px'
                                        : '5px'
                                }`
                      } - ${this.data.settings.column_gap ? this.data.settings.column_gap / 2 + 'px' : '5px'})`
                    : '100%'
            };
        },
        format_accept_type(type_list) {
            if(!type_list) return '';
            return '.' + type_list.replaceAll(' ', '').replaceAll(',',',.');
        }
    }
};
